def find(name):
    for c in (name, os.path.join("routes", name), os.path.join("templates", name)):
        if os.path.isfile(c):
            return c
def read(p): return open(p, encoding="utf-8").read()
def write(p, t): open(p, "w", encoding="utf-8", newline="").write(t)
def done(t, old, new):
    return new in t or (new.endswith(old) and new[:-len(old)] in t)

sp = find("search.py")
if not sp or not find("core.py"):
    print("search.py / core.py not found. Run this from the project folder (~/W)."); sys.exit(1)
if "citeauthors.apply(" not in read(sp):
    print("Run install_cite.py first (the Authors option is not installed yet)."); sys.exit(1)

def patch(name, pairs, optional=False):
    p = find(name)
    if not p:
        return None, [name + ": not found, skipped"]
    t = read(p); bad = []; n = 0
    for old, new in pairs:
        if done(t, old, new): continue
        if t.count(old) >= 1 and (name != "search.py" and name != "core.py" or t.count(old) == 1):
            t = t.replace(old, new, 1); n += 1
        else:
            bad.append(old[:60].replace("\n", " "))
    if bad:
        return None, [name + (" (card label)" if optional else "") + ": left alone, did not match: " + " | ".join(bad)]
    return (p, t, n), []

ok, warn = [], []
def apply(name, pairs, label):
    p = find(name)
    if not p:
        warn.append(name + ": not found, skipped"); return False
    t = read(p); n = 0; bad = []
    for old, new in pairs:
        if done(t, old, new): continue
        if t.count(old) == 1 or (name.endswith(".html") and t.count(old) > 1):
            t = t.replace(old, new, 1); n += 1
        else:
            bad.append(old[:60].replace("\n", " "))
    if bad:
        warn.append(label + ": left alone, did not match: " + " | ".join(bad)); return False
    if n:
        write(p + ".new", t); os.replace(p + ".new", p); ok.append(label)
    return True

core_ok = apply("core.py", SPEC["core.py"], "core.py")
srv_ok = apply("search.py", SPEC["search.py"], "search.py")
if srv_ok:
    target = os.path.join(os.path.dirname(find("core.py")) or ".", "refstyle.py")
    if not os.path.isfile(target) or read(target) != MOD:
        write(target, MOD); ok.append("refstyle.py")
    apply("citeauthors.py", SPEC["citeauthors.py"], "citeauthors.py (et al. in italic APA)")
    apply("search.py", OPT["search.py"], "search.py (result tagging)")
    apply("index.html", SPEC["index.html"], "index.html (cite window)")
    apply("citations.html", SPEC["citations.html"], "citations.html")
    apply("index.html", OPT["index.html"], "index.html (type label on cards)")
else:
    warn.append("pages were not touched because search.py did not match")
print("Updated:", ", ".join(ok) or "nothing (already done?)")
for w in warn: print("  warning:", w)
